/*
  template.sql
  純字串串接版：完全貼近既有腳本寫法，直接組出 @SQL_String 後 EXEC。
  適用於清分、匯出、結算、退票金額等月票類查詢。
*/

--DECLARE @EXEC_MERCHANT_NO VARCHAR(20) = '基隆區月票';
--DECLARE @EXEC_CPT_DATE DATE = '20260601';
DECLARE @DATE_FROM VARCHAR(8) = CONVERT(VARCHAR(6),DATEADD(M,-1,@EXEC_CPT_DATE),112)+'01'
DECLARE @DATE_TO VARCHAR(8) = CONVERT(VARCHAR(8),DATEADD(D,-1,DATEADD(M,1,@DATE_FROM)),112)

DECLARE @SQL_String VARCHAR(MAX)

SET @SQL_String =
 'SELECT sum(REFUND_AMOUNT)+sum(REFUND_FEE_AMOUNT) As 退票金額'
 + CHAR(13) + CHAR(10) + ',sum(SERVICE_FEE) As 清分服務費'
 + CHAR(13) + CHAR(10) + ',sum(RESERVE_AMOUNT_DEDUCT) As 預備金'
 + CHAR(13) + CHAR(10) + ',sum(REMITTANCE_FEE) As 匯費'
 + CHAR(13) + CHAR(10) + ',sum(ADJUSTMENT_AMOUNT) As 調整數'
 + CHAR(13) + CHAR(10) + ',sum(ABNORMAL_REFUND_AMOUNT) As 異常交易退回款'
 + CHAR(13) + CHAR(10) + ',sum(REFUND_AMOUNT) '
 + CHAR(13) + CHAR(10) + ' + sum(REFUND_FEE_AMOUNT) '
 + CHAR(13) + CHAR(10) + ' + sum(SERVICE_FEE) '
 + CHAR(13) + CHAR(10) + ' + sum(RESERVE_AMOUNT_DEDUCT) '
 + CHAR(13) + CHAR(10) + ' + sum(REMITTANCE_FEE) '
 + CHAR(13) + CHAR(10) + ' + sum(ADJUSTMENT_AMOUNT) '
 + CHAR(13) + CHAR(10) + ' - sum(ABNORMAL_REFUND_AMOUNT) As 總計'
 + CHAR(13) + CHAR(10) + 'FROM TPS_CM_SETTLE_SUM_D_TPASS_TOTAL'
 + CHAR(13) + CHAR(10) + 'WHERE CPT_DATE BETWEEN ''' + @DATE_FROM + ''' AND ''' + @DATE_TO + ''''
 + CHAR(13) + CHAR(10) + 'and MONTHLY_PASS_NAME=''' + @EXEC_MERCHANT_NO + ''''

EXEC (@SQL_String)